  // Funções utilitárias para correspondência e enriquecimento de signatários com Participantes Cadastrados
  const normalizeSignerName = useCallback((str?: string): string => {
    if (!str) return '';
    return String(str)
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .trim();
  }, []);

  const findCargoByName = useCallback((name?: string, cargosList: CargoCadastro[] = []): CargoCadastro | undefined => {
    if (!name || !cargosList || cargosList.length === 0) return undefined;
    const n = String(name).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
    if (!n) return undefined;

    // 1. Correspondência exata por Nome
    let found = cargosList.find(c => (c.nome || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim() === n);
    if (found) return found;

    // 2. Correspondência exata por Apelido
    found = cargosList.find(c => (c.apelido || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim() === n);
    if (found) return found;

    // 3. Correspondência de início de nome ou inclusão direta
    found = cargosList.find(c => {
      const cn = (c.nome || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
      return cn && (cn === n || cn.startsWith(n) || n.startsWith(cn));
    });
    if (found) return found;

    // 4. Correspondência especial por palavras-chave (ex: Samuel Cerqueira)
    if (n.includes('samuel') || n.includes('cerqueira')) {
      found = cargosList.find(c => {
        const cn = (c.nome || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
        return cn.includes('samuel') || cn.includes('cerqueira');
      });
      if (found) return found;
    }

    // 5. Correspondência por substrings mútuas
    found = cargosList.find(c => {
      const cn = (c.nome || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
      return cn && (cn.includes(n) || n.includes(cn));
    });
    if (found) return found;

    // 6. Correspondência por Cargo explícito (ex: "Testemunha 1", "Testemunha 2", "Testemunha")
    if (n.includes('testemunha')) {
      if (n.includes('2')) {
        found = cargosList.find(c => (c.cargo || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().includes('testemunha 2'));
        if (found) return found;
        const witnesses = cargosList.filter(c => (c.cargo || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().includes('testemunha'));
        if (witnesses.length > 1) return witnesses[1];
      } else {
        found = cargosList.find(c => (c.cargo || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().includes('testemunha 1'));
        if (found) return found;
        const witnesses = cargosList.filter(c => (c.cargo || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().includes('testemunha'));
        if (witnesses.length > 0) return witnesses[0];
      }
    }

    // 7. Correspondência por Cargo geral
    found = cargosList.find(c => {
      const cc = (c.cargo || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
      return cc && (cc === n || cc.startsWith(n) || n.startsWith(cc));
    });
    if (found) return found;

    // 8. Correspondência por E-mail cadastrado
    if (n.includes('@')) {
      found = cargosList.find(c => (c.email || '').toLowerCase().trim() === n);
      if (found) return found;
    }

    return undefined;
  }, []);

  // Helper to extract all official signers from the Brokerage Contract (Contrato de Corretagem)
  const getContractSignersList = useCallback((
    currentResult: ExtractionResult | null,
    cargosList: CargoCadastro[] = [],
    partiesList: any[] = []
  ) => {
    if (!currentResult) return [];
    const list: Array<{
      name: string;
      email: string;
      cpf: string;
      role: string;
      phone?: string;
    }> = [];

    const seenNames = new Set<string>();
    const seenEmails = new Set<string>();
    const seenCpfs = new Set<string>();

    const allPartySources = [
      ...((currentResult as any).commissioned_parties || []),
      ...((currentResult as any).commissionedParties || []),
      ...((currentResult as any).manual_waterfall?.participantes || []),
      ...(partiesList || []),
      ...(commissionedParties || [])
    ];

    // Mapear com precisão cargos flegados para ocultar e somar na Imobiliária
    const hiddenRolesSet = new Set<string>();
    const visibleRolesSet = new Set<string>();
    const hiddenRoleAndNameSet = new Set<string>();

    allPartySources.forEach((p: any) => {
      const rNorm = p.role ? p.role.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim() : '';
      if (!rNorm) return;
      if (p.hideAndSum) {
        hiddenRolesSet.add(rNorm);
        if (p.name) {
          p.name.split(',').forEach((n: string) => {
            const nNorm = n.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
            if (nNorm) hiddenRoleAndNameSet.add(`${rNorm}:::${nNorm}`);
          });
        }
      } else {
        visibleRolesSet.add(rNorm);
      }
    });

    const isPartyHidden = (role?: string, name?: string, partyObj?: any): boolean => {
      if (partyObj && typeof partyObj.hideAndSum === 'boolean') {
        return partyObj.hideAndSum;
      }
      if (role && isImobiliariaRole(role)) return false;
      if (name && isImobiliariaRole(name)) return false;

      const roleNorm = role ? role.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim() : '';
      const nameNorm = name ? name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim() : '';

      // Se temos o cargo e nome combinados, verificar se esse cargo específico foi flegado
      if (roleNorm && nameNorm && hiddenRoleAndNameSet.has(`${roleNorm}:::${nameNorm}`)) {
        return true;
      }

      // Se o cargo foi flegado para ocultação (e não possui nenhuma instância explícita visível)
      if (roleNorm && !visibleRolesSet.has(roleNorm)) {
        if (hiddenRolesSet.has(roleNorm)) return true;
        for (const hr of hiddenRolesSet) {
          if (hr === roleNorm) return true;
          const numRole = roleNorm.match(/\b([0-9]+)\b/)?.[1];
          const numHr = hr.match(/\b([0-9]+)\b/)?.[1];
          if (numRole && numHr && numRole !== numHr) {
            continue;
          }
          if (roleNorm.includes(hr) || hr.includes(roleNorm)) {
            return true;
          }
        }
      }
      return false;
    };

    // 1. Contratantes / Compradores (todos os proponentes compradores qualificados no contrato)
    const rawCustomers = (currentResult.customers && currentResult.customers.length > 0)
      ? currentResult.customers
      : [(currentResult as any).customer].filter(Boolean);
    const customers = rawCustomers.length > 0 ? rawCustomers : [];

    customers.forEach((cust: any, idx: number) => {
      if (cust && (cust.nome || cust.cpf)) {
        const cNome = cust.nome ? cust.nome.trim() : `Contratante ${idx + 1}`;
        const cEmail = cust.email ? cust.email.trim().toLowerCase() : '';
        const cCpfDigits = cust.cpf ? cust.cpf.replace(/\D/g, '') : '';
        const nameLower = cNome.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

        if (cEmail && seenEmails.has(cEmail)) return;
        if (cCpfDigits && cCpfDigits.length >= 11 && seenCpfs.has(cCpfDigits)) return;
        if (nameLower && seenNames.has(nameLower)) return;

        if (nameLower) seenNames.add(nameLower);
        if (cEmail) seenEmails.add(cEmail);
        if (cCpfDigits && cCpfDigits.length >= 11) seenCpfs.add(cCpfDigits);

        list.push({
          name: cNome,
          email: cust.email || '',
          cpf: cust.cpf || '',
          phone: cust.telefone || '',
          role: customers.length > 1 ? `Contratante ${idx + 1}` : 'Contratante'
        });
      }
    });

    if (list.length === 0) {
      list.push({
        name: 'Cliente Contratante',
        email: '',
        cpf: '',
        role: 'Contratante'
      });
      seenNames.add('cliente contratante');
    }

    // 2. Imobiliária Contratada (Intermediadora oficial no Contrato de Corretagem)
    list.push({
      name: 'RODOLFO JERRY IMÓVEIS LTDA',
      email: 'superintendenterodolfo@gmail.com',
      cpf: '29.881.101/0001-09',
      phone: '',
      role: 'Imobiliária'
    });
    seenNames.add('rodolfo jerry imoveis ltda');
    seenNames.add('rodolfo jerry imoveis');
    seenNames.add('rodolfo jerry');
    seenNames.add('imobiliaria');
    seenNames.add('imobiliaria intermediadora');
    seenEmails.add('superintendenterodolfo@gmail.com');
    seenCpfs.add('29881101000109');

    // 3. Corretores Associados e Equipe de Vendas (Item III e Cláusula de Partilha do Contrato)
    const activeParties = (currentResult as any).manual_waterfall?.participantes || (currentResult as any).commissionedParties || (currentResult as any).commissioned_parties || partiesList || [];

    activeParties.forEach((p: any) => {
      // Ignorar participantes flegados para ocultar ou somados na Imobiliária
      if (p.hideAndSum || isPartyHidden(p.role, p.name, p)) return;
      if (isImobiliariaRole(p.role) || isImobiliariaRole(p.name) || (p.name || '').toLowerCase().includes('rodolfo jerry')) return;
      if (!p.name || p.name.includes('___')) return;

      const names = p.name.split(',').map((n: string) => n.trim()).filter(Boolean);
      names.forEach((nameTrimmed: string) => {
        if (isPartyHidden(p.role, nameTrimmed, p)) return;
        const lower = nameTrimmed.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        if (seenNames.has(lower)) return;

        // Buscar dados completos no cadastro de Cargos/Participantes Cadastrados (e-mail estritamente idêntico)
        const match = findCargoByName(nameTrimmed, cargosList);
        const mEmail = match?.email ? match.email.trim() : '';
        const mCpfDigits = match?.cpf_cnpj ? match.cpf_cnpj.replace(/\D/g, '') : '';

        // Se o CPF já pertence à Imobiliária ou a outro signatário, não duplicar
        if (mEmail && seenEmails.has(mEmail.toLowerCase())) return;
        if (mCpfDigits && mCpfDigits.length >= 11 && seenCpfs.has(mCpfDigits)) return;

        seenNames.add(lower);
        if (mEmail) seenEmails.add(mEmail.toLowerCase());
        if (mCpfDigits && mCpfDigits.length >= 11) seenCpfs.add(mCpfDigits);

        list.push({
          name: match?.nome || nameTrimmed,
          email: mEmail,
          cpf: match?.cpf_cnpj || '',
          phone: match?.telefone || '',
          role: p.role || match?.cargo || 'Corretor'
        });
      });
    });

    // Incluir membros da equipe de vendas (salesTeam) não mapeados ainda
    if (currentResult.salesTeam) {
      const st = currentResult.salesTeam;
      const teamEntries = [
        { name: st.corretor1, role: 'Corretor 1' },
        { name: st.corretor2, role: 'Corretor 2' },
        { name: st.gerente, role: 'Gerente de Vendas' },
        { name: st.diretor, role: 'Diretor Comercial' },
        { name: st.coordenador, role: 'Coordenador' }
      ];

      teamEntries.forEach(entry => {
        if (entry.name && entry.name.trim() && !entry.name.includes('___')) {
          if (isPartyHidden(entry.role, entry.name)) return;
          if (isImobiliariaRole(entry.role) || isImobiliariaRole(entry.name) || entry.name.toLowerCase().includes('rodolfo jerry')) return;

          const lower = entry.name.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
          if (seenNames.has(lower)) return;

          const match = findCargoByName(entry.name, cargosList);
          const mEmail = match?.email ? match.email.trim() : '';
          const mCpfDigits = match?.cpf_cnpj ? match.cpf_cnpj.replace(/\D/g, '') : '';

          if (mEmail && seenEmails.has(mEmail.toLowerCase())) return;
          if (mCpfDigits && mCpfDigits.length >= 11 && seenCpfs.has(mCpfDigits)) return;

          seenNames.add(lower);
          if (mEmail) seenEmails.add(mEmail.toLowerCase());
          if (mCpfDigits && mCpfDigits.length >= 11) seenCpfs.add(mCpfDigits);

          list.push({
            name: match?.nome || entry.name.trim(),
            email: mEmail,
            cpf: match?.cpf_cnpj || '',
            phone: match?.telefone || '',
            role: entry.role || match?.cargo || 'Corretor'
          });
        }
      });
    }

    // 4. Testemunhas Instrumentárias (duas testemunhas obrigatórias para constarem no Assinafy e no contrato)
    const witnessCargos = (cargosList || []).filter(c => {
      const cCargo = (c.cargo || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
      const cNome = (c.nome || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
      return cCargo.includes('testemunha') || cNome.includes('testemunha') || cNome.includes('samuel') || cNome.includes('cerqueira');
    });

    const samuelCargo = findCargoByName('SAMUEL CERQUEIRA', cargosList);
    const t1ByCargo = (cargosList || []).find(c => (c.cargo || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().includes('testemunha 1'));
    const w1Cargo = t1ByCargo || samuelCargo || witnessCargos[0];

    const t2ByCargo = (cargosList || []).find(c => c !== w1Cargo && (c.cargo || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().includes('testemunha 2'));
    const w2Cargo = t2ByCargo || 
      witnessCargos.find(w => w !== w1Cargo) || 
      (cargosList || []).find(c => 
        c !== w1Cargo && (
          (c.cargo || '').toLowerCase().includes('secretar') ||
          (c.cargo || '').toLowerCase().includes('administrativ') ||
          (c.cargo || '').toLowerCase().includes('juridic') ||
          (c.cargo || '').toLowerCase().includes('apoio') ||
          (c.cargo || '').toLowerCase().includes('assistente')
        )
      ) ||
      (cargosList || []).find(c => 
        c !== w1Cargo && 
        !isImobiliariaRole(c.cargo) && 
        !isImobiliariaRole(c.nome) && 
        Boolean(c.email && c.email.trim())
      );

    list.push({
      name: w1Cargo?.nome ? w1Cargo.nome.trim() : (samuelCargo?.nome ? samuelCargo.nome.trim() : 'SAMUEL CERQUEIRA'),
      email: w1Cargo?.email ? w1Cargo.email.trim() : (samuelCargo?.email ? samuelCargo.email.trim() : ''),
      cpf: w1Cargo?.cpf_cnpj || samuelCargo?.cpf_cnpj || '',
      phone: w1Cargo?.telefone || samuelCargo?.telefone || '',
      role: 'Testemunha'
    });
    list.push({
      name: w2Cargo?.nome ? w2Cargo.nome.trim() : 'Testemunha 2',
      email: w2Cargo?.email ? w2Cargo.email.trim() : '',
      cpf: w2Cargo?.cpf_cnpj || '',
      phone: w2Cargo?.telefone || '',
      role: 'Testemunha'
    });

    // 5. Deduplicação final por chave de e-mail e CPF para garantir zero duplicatas na Assinafy
    const dedupedList: Array<{
      name: string;
      email: string;
      cpf: string;
      role: string;
      phone?: string;
    }> = [];
    const finalSeenEmails = new Set<string>();
    const finalSeenCpfs = new Set<string>();
    const finalSeenNames = new Set<string>();

    list.forEach(item => {
      const emailNorm = item.email ? String(item.email).trim().toLowerCase() : '';
      const cpfNorm = item.cpf ? String(item.cpf).replace(/\D/g, '') : '';
      const nameNorm = item.name ? String(item.name).trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '') : '';
      const isWitnessItem = (item.role || '').toLowerCase().includes('testemunha');

      if (emailNorm && finalSeenEmails.has(emailNorm) && !isWitnessItem) return;
      if (cpfNorm && cpfNorm.length >= 11 && finalSeenCpfs.has(cpfNorm) && !isWitnessItem) return;
      if (nameNorm && finalSeenNames.has(nameNorm) && !nameNorm.includes('testemunha') && !nameNorm.includes('samuel') && !nameNorm.includes('cerqueira')) return;

      if (emailNorm) finalSeenEmails.add(emailNorm);
      if (cpfNorm && cpfNorm.length >= 11) finalSeenCpfs.add(cpfNorm);
      if (nameNorm) finalSeenNames.add(nameNorm);

      dedupedList.push(item);
    });

    return dedupedList;
  }, [findCargoByName]);

  // Synchronize default signers from the Brokerage Contract when proposal result or commissionedParties changes
  useEffect(() => {
    if (!result) return;
    const list = getContractSignersList(result, cargos, commissionedParties);
    setEditingSigners(prev => {
      if (prev.length === list.length && JSON.stringify(prev) === JSON.stringify(list)) {
        return prev;
      }
      return list;
    });
  }, [result, cargos, commissionedParties, getContractSignersList]);

  // Sincronização estrita: quando um signatário possui nome cadastrado em Participantes Cadastrados, o e-mail deve ser idêntico ao do cadastro.
  // Signatários externos (que não constam na lista de cargos) são rigorosamente preservados sem substituição forçada.
  useEffect(() => {
    if (!editingSigners || editingSigners.length === 0 || !cargos || cargos.length === 0) return;

    let hasDiff = false;
    const synchronized = editingSigners.map((sig) => {
      if (!sig || !sig.name || !String(sig.name).trim()) return sig;

      // Buscar correspondência estrita por nome ou apelido no cadastro de cargos
      const sigNameNorm = String(sig.name).trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
      const match = cargos.find(c => {
        const cn = String(c.nome || '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        const ca = String(c.apelido || '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        return sigNameNorm && (cn === sigNameNorm || (ca && ca === sigNameNorm));
      });

      // Se a pessoa NÃO consta no cadastro de cargos, ela é externa: PRESERVAR EXATAMENTE COMO DIGITADO!
      if (!match) {
        return sig;
      }

      // Se a pessoa CONSTA no cadastro de cargos, garantir que o e-mail seja idêntico ao cadastrado
      const targetEmail = match.email ? String(match.email).trim() : '';
      const targetCpf = match.cpf_cnpj ? String(match.cpf_cnpj).trim() : (sig.cpf || '');
      const targetPhone = match.telefone ? String(match.telefone).trim() : (sig.phone || '');

      if (targetEmail && String(sig.email || '').trim() !== targetEmail) {
        hasDiff = true;
        return {
          ...sig,
          email: targetEmail,
          cpf: sig.cpf || targetCpf,
          phone: sig.phone || targetPhone
        };
      }
      return sig;
    });

    if (hasDiff) {
      setEditingSigners(synchronized);
    }
  }, [cargos, editingSigners]);

  // Função manual para sincronizar signatários da proposta com o Contrato de Corretagem
  const handleSyncContractSigners = () => {
    if (!result) {
      showToast("Nenhuma proposta carregada para sincronizar.", "error");
      return;
    }
    const list = getContractSignersList(result, cargos, commissionedParties);
    setEditingSigners(list);
    showToast("Tabela 'Quem Assina' sincronizada com os participantes da proposta!", "success");
  };

  const cleanDuplicateSigners = () => {
    const seenEmails = new Set<string>();
    const seenCpfs = new Set<string>();
    const seenPhones = new Set<string>();
    const seenNames = new Set<string>();
    const cleaned: any[] = [];
    let count = 0;

    editingSigners.forEach(s => {
      const email = s.email ? s.email.toLowerCase().trim() : '';
      const cpf = s.cpf ? s.cpf.replace(/\D/g, '') : '';
      const phoneDigits = s.phone ? s.phone.replace(/\D/g, '') : '';
      const phone = phoneDigits.length >= 10 ? phoneDigits : '';
      const name = s.name ? s.name.toLowerCase().trim().normalize('NFD').replace(/[\u0300-\u036f]/g, '') : '';

      let isDup = false;
      if (email && seenEmails.has(email)) isDup = true;
      else if (cpf && cpf.length >= 11 && seenCpfs.has(cpf)) isDup = true;
      else if (name && seenNames.has(name) && !isWitness(s.role)) isDup = true;
      else if (phone && seenPhones.has(phone) && !email) isDup = true;

      function isWitness(r?: string) {
        return (r || '').toLowerCase().includes('testemunha');
      }

      if (isDup) {
        count++;
        const target = cleaned.find(c => 
          (email && (c.email || '').toLowerCase().trim() === email) ||
          (cpf && (c.cpf || '').replace(/\D/g, '') === cpf) ||
          (name && (c.name || '').toLowerCase().trim().normalize('NFD').replace(/[\u0300-\u036f]/g, '') === name) ||
          (phone && (c.phone || '').replace(/\D/g, '') === phone)
        );
        if (target) {
          if (!target.cpf && s.cpf) target.cpf = s.cpf;
          if (!target.phone && s.phone) target.phone = s.phone;
          if (!target.email && s.email) target.email = s.email;
          if (s.role && target.role && !target.role.includes(s.role)) {
            target.role = `${target.role} / ${s.role}`;
          }
        }
      } else {
        if (email) seenEmails.add(email);
        if (cpf && cpf.length >= 11) seenCpfs.add(cpf);
        if (phone) seenPhones.add(phone);
        if (name && !isWitness(s.role)) seenNames.add(name);
        cleaned.push(s);
      }
    });

    setEditingSigners(cleaned);
    if (count > 0) {
      showToast(`${count} signatário(s) duplicado(s) unificado(s) com sucesso!`, 'success');
    } else {
      showToast("Não há signatários duplicados na lista.", "info");
    }
  };

  const duplicateSignerWarning = useMemo(() => {
    const emails = new Set<string>();
    const cpfs = new Set<string>();
    const phones = new Set<string>();
    const names = new Set<string>();
    const dupList: string[] = [];

    for (const s of editingSigners) {
      const email = s.email ? s.email.toLowerCase().trim() : '';
      const cpf = s.cpf ? s.cpf.replace(/\D/g, '') : '';
      const phoneDigits = s.phone ? s.phone.replace(/\D/g, '') : '';
      const phone = phoneDigits.length >= 10 ? phoneDigits : '';
      const name = s.name ? s.name.toLowerCase().trim().normalize('NFD').replace(/[\u0300-\u036f]/g, '') : '';
      const isWitness = (s.role || '').toLowerCase().includes('testemunha');

      if (email && emails.has(email)) {
        dupList.push(`${s.name || 'Signatário'} (E-mail repetido: ${email})`);
      } else if (email) {
        emails.add(email);
      }

      if (cpf && cpf.length >= 11 && cpfs.has(cpf)) {
        dupList.push(`${s.name || 'Signatário'} (CPF/CNPJ repetido)`);
      } else if (cpf && cpf.length >= 11) {
        cpfs.add(cpf);
      }

      if (phone && phones.has(phone) && !email) {
        dupList.push(`${s.name || 'Signatário'} (WhatsApp repetido)`);
      } else if (phone) {
        phones.add(phone);
      }

      if (name && names.has(name) && !isWitness) {
        dupList.push(`${s.name || 'Signatário'} (Nome repetido)`);
      } else if (name && !isWitness) {
        names.add(name);
      }
    }
    return dupList;
  }, [editingSigners]);

  const handleCameraCapture = async (id: string) => {
    setActiveCaptureId(id);
    
    if (Capacitor.isNativePlatform()) {
      try {
        // Explicitly check/request permissions for native
        const permissions = await CapCamera.checkPermissions();
        if (permissions.camera !== 'granted') {
          const request = await CapCamera.requestPermissions();
          if (request.camera !== 'granted') {
            showToast('Permissão de câmera negada', 'error');
            return;
          }
        }

        const image = await CapCamera.getPhoto({
          quality: 90,
          allowEditing: false,
          resultType: CameraResultType.Uri,
          source: CameraSource.Camera
        });

        if (image.webPath) {
          const response = await fetch(image.webPath);
          const blob = await response.blob();
          const file = new File([blob], `capture_${Date.now()}.jpg`, { type: 'image/jpeg' });
          handleFileChange(id, file);
        }
      } catch (err) {
        console.error('Error capturing image with Capacitor:', err);
      }
    } else {
      if (cameraInputRef.current) {
        cameraInputRef.current.value = '';
        cameraInputRef.current.click();
      }
    }
  };

  const handleDocumentScan = async (id: string) => {
    setActiveCaptureId(id);
    
    if (Capacitor.isNativePlatform()) {
      try {
        const { scannedImages } = await DocumentScanner.scanDocument();
        if (scannedImages && scannedImages.length > 0) {
          const response = await fetch(Capacitor.convertFileSrc(scannedImages[0]));
          const blob = await response.blob();
          const file = new File([blob], `scan_${Date.now()}.jpg`, { type: 'image/jpeg' });
          handleFileChange(id, file);
        }
      } catch (err) {
        console.error('Error scanning document with Capacitor:', err);
        // Fallback to camera capture if scanner fails
        handleCameraCapture(id);
      }
    } else {
      // Fallback for web: just use camera
      handleCameraCapture(id);
    }
  };

  const handleFileUpload = (id: string) => {
    setActiveCaptureId(id);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
      fileInputRef.current.click();
    }
  };

  const isAdmin = userRole === 'admin' || user?.email?.toLowerCase() === 'propostasrej@gmail.com';

  // Empreendimentos and Properties Management State
  const [showEmpreendimentoModal, setShowEmpreendimentoModal] = useState(false);
  const [editingEmpreendimento, setEditingEmpreendimento] = useState<Empreendimento | null>(null);
  const [empreendimentoForm, setEmpreendimentoForm] = useState({
    nome: '',
    construtora: '',
    localizacao: '',
    endereco: '',
    tabela_base_id: '',
    status: 'ATIVO' as 'ATIVO' | 'INATIVO',
    regras_comissao: [] as RegraComissao[],
    modelo_rateio: [] as ModeloRateioCargo[]
  });

  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      if (event.data?.type === 'GOOGLE_AUTH_SUCCESS') {
        setNeedsGoogleAuth(false);
        if (isExportingDashboard) {
          exportDashboardToGoogleSheets();
        } else if (isUploadingToDrive) {
          uploadToDrive();
        } else if (isExportingToSheets) {
          exportToGoogleSheets();
        } else if (savedExtractions.length > 0) {
          autoSyncToSheets(savedExtractions);
        }
      } else if (event.data?.type === 'TRIGGER_ASSINAFY_CONTRACT' || event.data?.type === 'TRIGGER_CLICKSIGN_CONTRACT') {
        setClicksignDocType('contract');
        setAssinafyDocType('contract');
        if (result) {
          const list = getContractSignersList(result, cargos, commissionedParties);
          setEditingSigners(list);
        }
        setShowClicksignModal(true);
        showToast("Painel ClickSign ativado para o Contrato de Corretagem! Confira os signatários e e-mails.", "info");
      }
    };
    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, [result, view, savedExtractions, isUploadingToDrive, isExportingToSheets, isExportingDashboard, cargos, commissionedParties, getContractSignersList]);

  const ensureGoogleAuth = async (): Promise<boolean> => {
    // 1. Verificar se o backend já possui token válido ativo
    try {
      const statusRes = await fetch('/api/auth/google/status', { credentials: 'include' });
      const statusData = await statusRes.json();
      if (statusData.isAuthenticated) {
        setNeedsGoogleAuth(false);
        return true;
      }
    } catch (e) {}

    // 2. Fluxo Client-Side direto via Firebase Auth Popup (elimina erro redirect_uri_mismatch)
    try {
      const provider = new GoogleAuthProvider();
      provider.addScope('https://www.googleapis.com/auth/spreadsheets');
      provider.addScope('https://www.googleapis.com/auth/drive');
      provider.addScope('https://www.googleapis.com/auth/drive.file');
      provider.setCustomParameters({ prompt: 'consent' });

      const userCred = await signInWithPopup(auth, provider);
      const credential = GoogleAuthProvider.credentialFromResult(userCred);
      const accessToken = credential?.accessToken;

      if (accessToken) {
        await fetch('/api/auth/google/store-tokens', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ tokens: { access_token: accessToken } })
        }).catch(() => {});

        setNeedsGoogleAuth(false);
        showToast('Google Sheets e Drive autorizados com sucesso!', 'success');
        return true;
      }
    } catch (err: any) {
      if (err?.code !== 'auth/popup-closed-by-user') {
        console.error('[Google Auth] Erro ao autenticar via popup:', err);
        showToast('Não foi possível conectar ao Google: ' + (err.message || 'Tente novamente'), 'error');
      }
    }
    return false;
  };

  const exportDashboardToGoogleSheets = async () => {
    if (savedExtractions.length === 0) return;
    
    setIsExportingDashboard(true);
    try {
      const hasAuth = await ensureGoogleAuth();
      if (!hasAuth) {
        setIsExportingDashboard(false);
        return;
      }

      const targetList = (dashboardDateFilter !== 'all' || dashboardStatusFilter !== 'todos' || searchQuery)
        ? filteredExtractions
        : savedExtractions;

      if (targetList.length === 0) {
        showToast('Nenhuma proposta para exportar com os filtros atuais.', 'info');
        setIsExportingDashboard(false);
        return;
      }

      const exportData = targetList.map(ext => {
        // Handle potential missing fields or legacy data
        const customers = (ext.customers || [(ext as any).customer]).filter(Boolean);
        const payments = ext.payments || [];
        const totalValue = ext.valorTotalProposta || payments.reduce((acc, p) => acc + (p.valorTotal || 0), 0);
        const pDate = getProposalDate(ext);
        
        return {
          'Data': pDate && !isNaN(pDate.getTime()) ? pDate.toLocaleDateString('pt-BR') : '-',
          'Empreendimento': ext.property?.empreendimento || '-',
          'Torre': ext.property?.torre || '-',
          'Unidade': ext.property?.unidade || '-',
          'Corretor 1': ext.sales_team?.corretor1 || '-',
          'Corretor 2': ext.sales_team?.corretor2 || '-',
          'Comprador': customers[0]?.nome || '-',
          'CPF': customers[0]?.cpf || '-',
          'Telefone': customers[0]?.telefone || '-',
          'Email': customers[0]?.email || '-',
          'Cidade': ext.address?.cidade || '-',
          'Estado': ext.address?.estado || '-',
          'Valor Total Proposta': totalValue.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }),
          'PROPOSTA': ext.proposta_status || 'AGUARDANDO APROVAÇÃO',
          'CVC': ext.cvc_status || 'PENDENTE',
          'CORRETAGEM': ext.corretagem_status || 'PENDENTE',
          'FORMA DE PAGAMENTO': ext.forma_pagamento_comissao || 'PAGADORIA',
          'Status': ext.status || '-',
          'Informações Adicionais': ext.informacoes_adicionais || '-'
        };
      });

      // Get existing spreadsheet ID from Firestore
      let existingId = null;
      const settingsRef = doc(db, 'user_settings', user.uid);
      try {
        const settingsSnap = await getDoc(settingsRef);
        if (settingsSnap.exists()) {
          existingId = settingsSnap.data().dashboard_spreadsheet_id;
        }
      } catch (err) {
        console.warn("Could not fetch user settings, falling back to localStorage", err);
        existingId = localStorage.getItem('dashboard_spreadsheet_id');
      }
      
      const { spreadsheetUrl, spreadsheetId } = await safeFetchJson('/api/export/sheets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          data: exportData,
          title: `Dashboard de Extrações - ${new Date().toLocaleDateString()}`,
          spreadsheetId: existingId
        })
      });

      if (spreadsheetId) {
        // Save back to Firestore
        try {
          await setDoc(settingsRef, { dashboard_spreadsheet_id: spreadsheetId }, { merge: true });
        } catch (err) {
          console.error("Error saving dashboard spreadsheet ID to Firestore:", err);
        }
        localStorage.setItem('dashboard_spreadsheet_id', spreadsheetId);
      }
      window.open(spreadsheetUrl, '_blank');
    } catch (error: any) {
      console.error('Erro ao exportar dashboard:', error);
      if (error.status === 401 || (error.data && error.data.reauth)) {
        setNeedsGoogleAuth(true);
        alert('Sua sessão do Google expirou ou precisa de reautorização. Por favor, utilize o botão "Reconectar agora" no topo para reautenticar.');
      } else {
        alert('Erro ao exportar dashboard para o Google Sheets: ' + (error.message || error));
      }
    } finally {
      setIsExportingDashboard(false);
    }
  };

  const exportToGoogleSheets = async () => {
    if (!result) return;
    
    setIsExportingToSheets(true);
    try {
      const hasAuth = await ensureGoogleAuth();
      if (!hasAuth) {
        setIsExportingToSheets(false);
        return;
      }

      // Prepare data
      const exportData = result.payments.map(p => ({
        Empreendimento: result.property.empreendimento,
        Unidade: result.property.unidade,
        Torre: result.property.torre || '-',
        'Corretor 1': result.salesTeam?.corretor1 || '-',
        'Corretor 2': result.salesTeam?.corretor2 || '-',
        Comprador: result.customers[0]?.nome || '-',
        'Valor Total Proposta': result.valorTotalProposta || '-',
        Quantidade: p.quantidade,
        Tipo: p.tipo,
        'Valor Unitário': p.valorUnitario,
        Vencimento: p.vencimento,
        Total: p.valorTotal
      }));

      const storageKey = `spreadsheet_id_${result.id || 'temp'}`;
      const existingId = result.spreadsheet_id || localStorage.getItem(storageKey);

      const { spreadsheetUrl, spreadsheetId } = await safeFetchJson('/api/export/sheets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          data: exportData,
          title: `Extração - ${result.property.empreendimento} - ${new Date().toLocaleDateString()}`,
          spreadsheetId: existingId
        })
      });

      if (spreadsheetId) {
        // Update local state and Firestore if we have an ID
        setResult(prev => prev ? { ...prev, spreadsheet_id: spreadsheetId } : null);
        
        if (result.id) {
          try {
            await updateDoc(doc(db, 'entrada', result.id), { spreadsheet_id: spreadsheetId });
          } catch (err) {
            console.error("Error updating extraction spreadsheet ID in Firestore:", err);
          }
        }
        localStorage.setItem(storageKey, spreadsheetId);
      }
      window.open(spreadsheetUrl, '_blank');
      alert('Tabela exportada com sucesso para o Google Sheets!');
    } catch (error: any) {
      console.error('Erro ao exportar:', error);
      if (error.status === 401 || (error.data && error.data.reauth)) {
        setNeedsGoogleAuth(true);
        const reauthed = await ensureGoogleAuth();
        if (reauthed) {
          exportToGoogleSheets();
        }
        return;
      }
      alert(error.message || 'Erro ao exportar para o Google Sheets. Tente novamente.');
    } finally {
      setIsExportingToSheets(false);
    }
  };

  const uploadToDrive = async () => {
    const filesToUpload = docs.filter(d => d.file !== null);
    if (filesToUpload.length === 0) {
      alert('Nenhum documento anexado para salvar. Se você está editando uma extração antiga, anexe os arquivos novamente para enviá-los ao Drive.');
      return;
    }

    setIsUploadingToDrive(true);
    try {
      const hasAuth = await ensureGoogleAuth();
      if (!hasAuth) {
        setIsUploadingToDrive(false);
        return;
      }
      
      // Check if we have drive access already, or if we need a fresh token for the new scopes
      // We handle this via the 401 response from the server which triggers reauth
      
      let successCount = 0;
      
      // Construct folder name: EMPREENDIMENTO - UNIDADE - TORRE - CLIENTE
      let folderName = "";
      if (result) {
        const emp = (result.property?.empreendimento || "SEM_EMPREENDIMENTO").trim();
        const uni = (result.property?.unidade || "SEM_UNIDADE").trim();
        const tor = (result.property?.torre || "").trim();
        const customerName = (result.customers?.[0]?.nome || "SEM_NOME").trim();
        
        folderName = `${emp}${tor ? ' - ' + tor : ''} - UN ${uni} - ${customerName}`.toUpperCase();
      }

      let folderUrl = "";
      let lastError = null;
      for (const doc of filesToUpload) {
        if (!doc.file) continue;

        const formData = new FormData();
        formData.append('file', doc.file);
        if (folderName) {
          formData.append('folderName', folderName);
        }
        formData.append('customFileName', doc.name); // Pass the document type (RG, CPF, etc)

        try {
          const data = await safeFetchJson('/api/drive/upload', {
            method: 'POST',
            body: formData,
            credentials: 'include'
          });

          if (data.folderUrl) {
            folderUrl = data.folderUrl;
          }
          successCount++;
        } catch (err: any) {
          if (err.status === 401 || (err.data && err.data.reauth)) {
            setNeedsGoogleAuth(true);
            const reauthed = await ensureGoogleAuth();
            if (reauthed) {
              uploadToDrive();
            }
            return; // Stop and wait for auth
          }
          console.error(`[Drive] Falha no upload de ${doc.file.name}:`, err);
          lastError = err.message || 'Erro desconhecido';
        }
      }

      if (successCount > 0) {
        // Update Firestore if we have a result ID and a folder URL
        if (result?.id && folderUrl) {
          try {
            const docRef = doc(db, 'entrada', result.id);
            await updateDoc(docRef, {
              drive_link: folderUrl,
              updated_at: new Date().toISOString()
            });
            
            // Update local state
            setResult(prev => prev ? { ...prev, drive_link: folderUrl } : null);
            setSavedExtractions(prev => prev.map(ext => 
              ext.id === result.id ? { ...ext, drive_link: folderUrl } : ext
            ));
          } catch (err) {
            console.error('Erro ao atualizar link do Drive no Firestore:', err);
          }
        }
        alert(`${successCount} documento(s) salvo(s) com sucesso no Google Drive!`);
      } else {
        throw new Error(lastError || 'Nenhum arquivo pôde ser enviado.');
      }
    } catch (error: any) {
      console.error('Erro ao salvar no Drive:', error);
      alert(error.message || 'Erro ao salvar documentos no Google Drive. Tente novamente.');
    } finally {
      setIsUploadingToDrive(false);
    }
  };

  const syncDocsToFirebaseStorage = async (
    targetResult: ExtractionResult | null,
    targetDocs: DocumentState[]
  ): Promise<{ storedFiles: StoredProposalFile[]; storageFolder: string; uploadedNowCount: number }> => {
    if (!user) {
      throw new Error('Faça login para enviar documentos ao Firebase Storage.');
    }

    const existingFiles: StoredProposalFile[] = [...(targetResult?.stored_files || [])];
    const storageFolder =
      targetResult?.storage_folder ||
      buildProposalStorageKey(
        targetResult?.id,
        targetResult?.property?.empreendimento,
        targetResult?.property?.unidade,
        targetResult?.customers?.[0]?.nome
      );

    const filesToUpload = targetDocs.filter((docItem) => {
      if (!docItem.file) return false;
      return !existingFiles.some(
        (f) => f.fileName === docItem.file!.name && f.size === docItem.file!.size
      );
    });

    if (filesToUpload.length === 0) {
      return { storedFiles: existingFiles, storageFolder, uploadedNowCount: 0 };
    }

    const progressPerFile = new Array<number>(filesToUpload.length).fill(0);
    const uploadedResults = await Promise.all(
      filesToUpload.map((docItem, idx) =>
        uploadProposalFileToStorage({
          proposalKey: storageFolder,
          ownerUid: user.uid,
          docId: docItem.id,
          docType: docItem.name,
          file: docItem.file!,
          onProgress: (pct) => {
            progressPerFile[idx] = pct;
            const totalPct = progressPerFile.reduce((acc, v) => acc + v, 0);
            setStorageUploadProgress(Math.round(totalPct / filesToUpload.length));
          }
        })
      )
    );

    return {
      storedFiles: [...existingFiles, ...uploadedResults],
      storageFolder,
      uploadedNowCount: uploadedResults.length
    };
  };

  const uploadToFirebaseStorage = async () => {
    if (!user) {
      showToast('Você precisa estar autenticado para salvar no Firebase Storage.', 'error');
      return;
    }

    const filesToUpload = docs.filter((d) => d.file !== null);
    if (filesToUpload.length === 0) {
      showToast('Nenhum arquivo anexado na fila de upload. Use "Enviar Arquivo" no painel de Storage abaixo para anexar novos documentos.', 'info');
      return;
    }

    setIsUploadingToStorage(true);
    setStorageUploadProgress(0);
    setStorageError(null);

    try {
      const { storedFiles, storageFolder, uploadedNowCount } = await syncDocsToFirebaseStorage(result, docs);

      if (result) {
        setResult((prev) =>
          prev ? { ...prev, stored_files: storedFiles, storage_folder: storageFolder } : null
        );
      }

      if (result?.id) {
        await updateDoc(doc(db, 'entrada', result.id), {
          stored_files: storedFiles,
          storage_folder: storageFolder,
          updated_at: new Date().toISOString()
        });
        setSavedExtractions((prev) =>
          prev.map((ext) =>
            ext.id === result.id ? { ...ext, stored_files: storedFiles, storage_folder: storageFolder } : ext
          )
        );
      }

      if (uploadedNowCount > 0) {
        showToast(`${uploadedNowCount} arquivo(s) salvo(s) no Firebase Storage!`, 'success');
      } else {
        showToast('Todos os documentos anexados já estão sincronizados no Firebase Storage.', 'info');
      }
    } catch (err: any) {
      console.error('[Firebase Storage] Erro no upload:', err);
      const msg = err?.message || 'Erro ao enviar arquivos para o Firebase Storage.';
      setStorageError(msg);
      showToast(msg, 'error');
    } finally {
      setIsUploadingToStorage(false);
      setStorageUploadProgress(0);
    }
  };

  const handleDirectStorageUpload = async (filesList: FileList | null) => {
    if (!filesList || filesList.length === 0) return;
    if (!user) {
      showToast('Faça login para enviar arquivos para o Firebase Storage.', 'error');
      return;
    }

    setIsUploadingToStorage(true);
    setStorageUploadProgress(0);
    setStorageError(null);

    try {
      const existingFiles: StoredProposalFile[] = [...(result?.stored_files || [])];
      const storageFolder =
        result?.storage_folder ||
        buildProposalStorageKey(
          result?.id,
          result?.property?.empreendimento,
          result?.property?.unidade,
          result?.customers?.[0]?.nome
        );

      const selectedFiles = Array.from(filesList);
      for (let i = 0; i < selectedFiles.length; i++) {
        const file = selectedFiles[i];
        const stored = await uploadProposalFileToStorage({
          proposalKey: storageFolder,
          ownerUid: user.uid,
          docId: `direct_${Date.now()}_${i}`,
          docType: directStorageDocType || 'Documento Adicional',
          file,
          onProgress: (pct) => {
            const overall = Math.round(((i + pct / 100) / selectedFiles.length) * 100);
            setStorageUploadProgress(overall);
          }
        });
        existingFiles.push(stored);
      }

      if (result) {
        setResult((prev) =>
          prev ? { ...prev, stored_files: existingFiles, storage_folder: storageFolder } : null
        );
      }

      if (result?.id) {
        await updateDoc(doc(db, 'entrada', result.id), {
          stored_files: existingFiles,
          storage_folder: storageFolder,
          updated_at: new Date().toISOString()
        });
        setSavedExtractions((prev) =>
          prev.map((ext) =>
            ext.id === result.id ? { ...ext, stored_files: existingFiles, storage_folder: storageFolder } : ext
          )
        );
      }

      showToast(`${selectedFiles.length} arquivo(s) enviado(s) para o Firebase Storage!`, 'success');
    } catch (err: any) {
      console.error('[Firebase Storage] Erro no upload direto:', err);
      const msg = err?.message || 'Erro ao enviar arquivo para o Firebase Storage.';
      setStorageError(msg);
      showToast(msg, 'error');
    } finally {
      setIsUploadingToStorage(false);
      setStorageUploadProgress(0);
    }
  };

  const handleDeleteStorageFile = async (
    fileItem: StoredProposalFile,
    targetExtraction?: SavedExtraction | null
  ) => {
    if (!user) return;
    if (!confirm(`Excluir "${fileItem.fileName}" do Firebase Storage?`)) return;

    try {
      await deleteProposalFileFromStorage(fileItem.storagePath);

      const proposalId = targetExtraction?.id || result?.id;
      const sourceFiles = targetExtraction ? (targetExtraction.stored_files || []) : (result?.stored_files || []);
      const updatedFiles = sourceFiles.filter((f) => f.id !== fileItem.id && f.storagePath !== fileItem.storagePath);

      if (result && (!proposalId || result.id === proposalId)) {
        setResult((prev) => (prev ? { ...prev, stored_files: updatedFiles } : null));
      }

      if (targetExtraction && storageModalExtraction?.id === targetExtraction.id) {
        setStorageModalExtraction((prev) => (prev ? { ...prev, stored_files: updatedFiles } : null));
      }

      if (proposalId) {
        await updateDoc(doc(db, 'entrada', proposalId), {
          stored_files: updatedFiles,
          updated_at: new Date().toISOString()
        });
        setSavedExtractions((prev) =>
          prev.map((ext) => (ext.id === proposalId ? { ...ext, stored_files: updatedFiles } : ext))
        );
      }

      showToast('Arquivo removido do Firebase Storage.', 'success');
    } catch (err: any) {
      console.error('[Firebase Storage] Erro ao excluir arquivo:', err);
      showToast(err?.message || 'Erro ao excluir arquivo do Firebase Storage.', 'error');
    }
  };

  const handleLoadStorageFileToDocs = async (fileItem: StoredProposalFile) => {
    try {
      showToast(`Baixando "${fileItem.fileName}" do Firebase Storage...`, 'info');
      const file = await fetchStorageFileAsFile(fileItem);
      setDocs((prev) => {
        const matchedIdx = prev.findIndex(
          (d) => !d.file && (d.id === fileItem.docId || d.name.toLowerCase() === fileItem.docType.toLowerCase())
        );
        if (matchedIdx !== -1) {
          const next = [...prev];
          next[matchedIdx] = { ...next[matchedIdx], file, status: 'completed' };
          return next;
        }
        return [
          ...prev,
          {
            id: `storage_${fileItem.id}`,
            name: fileItem.docType || 'Documento do Storage',
            file,
            status: 'completed',
            required: false
          }
        ];
      });
      showToast(`"${fileItem.fileName}" carregado para extração / Ficha+Docs!`, 'success');
    } catch (err: any) {
      console.error('[Firebase Storage] Erro ao carregar arquivo:', err);
      showToast(err?.message || 'Não foi possível carregar o arquivo do Storage.', 'error');
    }
  };

  const handleArchiveGeneratedPdfToStorage = async (kind: 'contrato' | 'ficha') => {
    if (!result || !user) {
      showToast('Autentique-se e carregue uma proposta para arquivar no Firebase Storage.', 'error');
      return;
    }

    setIsUploadingToStorage(true);
    setStorageUploadProgress(15);
    setStorageError(null);

    try {
      const storageFolder =
        result.storage_folder ||
        buildProposalStorageKey(
          result.id,
          result.property?.empreendimento,
          result.property?.unidade,
          result.customers?.[0]?.nome
        );

      let blob: Blob;
      let fileName: string;
      let docType: string;

      if (kind === 'contrato') {
        const finalSigners = editingSigners && editingSigners.length > 0
          ? editingSigners
          : getContractSignersList(result, cargos, commissionedParties);
        const { base64, fileName: generatedName } = await generateContratoPdfBase64(result, finalSigners);
        const byteCharacters = atob(base64);
        const byteNumbers = new Array(byteCharacters.length);
        for (let i = 0; i < byteCharacters.length; i++) {
          byteNumbers[i] = byteCharacters.charCodeAt(i);
        }
        blob = new Blob([new Uint8Array(byteNumbers)], { type: 'application/pdf' });
        fileName = generatedName;
        docType = 'Contrato de Corretagem (PDF)';
      } else {
        const pdfBytes = await compileUnifiedFichaBlob(result);
        blob = new Blob([pdfBytes], { type: 'application/pdf' });
        const customerName = result.customers?.[0]?.nome?.replace(/\s+/g, '_').toLowerCase();
        fileName = customerName
          ? `ficha_completa_${customerName}.pdf`
          : `ficha_completa_${result.property?.unidade || 'unidade'}.pdf`;
        docType = 'Ficha Cadastral + Docs (PDF)';
      }

      const stored = await uploadProposalBlobToStorage({
        proposalKey: storageFolder,
        ownerUid: user.uid,
        docType,
        fileName,
        blob,
        onProgress: (pct) => setStorageUploadProgress(pct)
      });

      const updatedFiles = [...(result.stored_files || []), stored];
      setResult((prev) =>
        prev ? { ...prev, stored_files: updatedFiles, storage_folder: storageFolder } : null
      );

      if (result.id) {
        await updateDoc(doc(db, 'entrada', result.id), {
          stored_files: updatedFiles,
          storage_folder: storageFolder,
          updated_at: new Date().toISOString()
        });
        setSavedExtractions((prev) =>
          prev.map((ext) =>
            ext.id === result.id ? { ...ext, stored_files: updatedFiles, storage_folder: storageFolder } : ext
          )
        );
      }

      showToast(`${docType} arquivado no Firebase Storage!`, 'success');
    } catch (err: any) {
      console.error('[Firebase Storage] Erro ao arquivar PDF:', err);
      const msg = err?.message || 'Erro ao arquivar PDF no Firebase Storage.';
      setStorageError(msg);
      showToast(msg, 'error');
    } finally {
      setIsUploadingToStorage(false);
      setStorageUploadProgress(0);
    }
  };
  const logoutGoogle = async () => {
    if (!confirm('Deseja desconectar sua conta Google? Suas permissões serão solicitadas novamente na próxima exportação.')) return;
    try {
      await fetch('/api/auth/google/logout', { method: 'POST', credentials: 'include' });
      alert('Conta Google desconectada com sucesso.');
    } catch (err) {
      console.error('Erro ao desconectar Google:', err);
    }
  };

  const formatInputDate = (dStr?: string): string => {
    if (!dStr) return '';
    const match = dStr.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);
    if (match) {
      const day = match[3].padStart(2, '0');
      const month = match[2].padStart(2, '0');
      const year = match[1];
      return `${day}/${month}/${year}`;
    }
    const d = parseFlexibleDate(dStr);
    return d ? d.toLocaleDateString('pt-BR') : dStr;
  };

  const parseFlexibleDate = (dateVal: any): Date | null => {
    if (!dateVal) return null;
    if (dateVal instanceof Date) return isNaN(dateVal.getTime()) ? null : dateVal;
    if (typeof dateVal === 'object' && typeof dateVal.toDate === 'function') {
      try { return dateVal.toDate(); } catch {}
    }
    if (typeof dateVal === 'object' && typeof dateVal.seconds === 'number') {
      return new Date(dateVal.seconds * 1000);
    }
    if (typeof dateVal === 'number') {
      return new Date(dateVal);
    }
    if (typeof dateVal !== 'string') return null;
    const str = dateVal.trim();
    if (!str) return null;

    // Check Brazilian format: DD/MM/YYYY or DD-MM-YYYY (with optional time)
    const brMatch = str.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})(?:[T\s](\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?/);
    if (brMatch) {
      const day = parseInt(brMatch[1], 10);
      const month = parseInt(brMatch[2], 10) - 1;
      const year = parseInt(brMatch[3], 10);
      const hour = brMatch[4] ? parseInt(brMatch[4], 10) : 0;
      const minute = brMatch[5] ? parseInt(brMatch[5], 10) : 0;
      const second = brMatch[6] ? parseInt(brMatch[6], 10) : 0;
      const d = new Date(year, month, day, hour, minute, second);
      return isNaN(d.getTime()) ? null : d;
    }

    // Check ISO format: YYYY-MM-DD or YYYY/MM/DD
    const isoMatch = str.match(/^(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})(?:[T\s](\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?/);
    if (isoMatch) {
      const year = parseInt(isoMatch[1], 10);
      const month = parseInt(isoMatch[2], 10) - 1;
      const day = parseInt(isoMatch[3], 10);
      const hour = isoMatch[4] ? parseInt(isoMatch[4], 10) : 0;
      const minute = isoMatch[5] ? parseInt(isoMatch[5], 10) : 0;
      const second = isoMatch[6] ? parseInt(isoMatch[6], 10) : 0;

      // If it contains a timezone offset (Z or +HH:mm), allow native Date parse
      if (str.includes('Z') || str.match(/[+-]\d{2}:?\d{2}$/)) {
        const d = new Date(str);
        if (!isNaN(d.getTime())) return d;
      }

      // For date-only inputs (like input type="date" values "2026-10-01"), ALWAYS parse as local date!
      const d = new Date(year, month, day, hour, minute, second);
      return isNaN(d.getTime()) ? null : d;
    }

    const d = new Date(str);
    return isNaN(d.getTime()) ? null : d;
  };

  const getProposalDate = (ext: any): Date => {
    if (!ext) return new Date();
    // Prioritize actual proposal entry/creation dates
    const candidates = [
      ext.data_entrada,
      ext.created_at,
      ext.data_proposta,
      ext.dataProposta,
      ext.data_venda,
      ext.data
    ];
    for (const c of candidates) {
      if (c) {
        const d = parseFlexibleDate(c);
        if (d && !isNaN(d.getTime())) return d;
      }
    }
    // Secondary fallback: first payment due date
    if (ext.payments && ext.payments.length > 0 && ext.payments[0]?.vencimento) {
      const d = parseFlexibleDate(ext.payments[0].vencimento);
      if (d && !isNaN(d.getTime())) return d;
    }
    return new Date();
  };

  const checkDateInPeriod = (
    proposalOrDate: any,
    period: string,
    customStart?: string,
    customEnd?: string
  ): boolean => {
    if (period === 'all') return true;

    const d = typeof proposalOrDate === 'object' && proposalOrDate !== null
      ? getProposalDate(proposalOrDate)
      : (parseFlexibleDate(proposalOrDate) || new Date());

    if (!d || isNaN(d.getTime())) return true;
    
    const now = new Date();

    if (period === 'today') {
      const today = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0, 0);
      const endToday = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999);
      return d >= today && d <= endToday;
    }

    if (period === 'this_week') {
      const day = now.getDay();
      const diff = now.getDate() - day + (day === 0 ? -6 : 1);
      const monday = new Date(now.getFullYear(), now.getMonth(), diff, 0, 0, 0, 0);
      const sunday = new Date(now.getFullYear(), now.getMonth(), diff + 6, 23, 59, 59, 999);
      return d >= monday && d <= sunday;
    }

    if (period === 'this_month') {
      const firstDay = new Date(now.getFullYear(), now.getMonth(), 1, 0, 0, 0, 0);
      const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59, 999);
      return d >= firstDay && d <= lastDay;
    }

    if (period === 'last_month') {
      const firstDayLastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1, 0, 0, 0, 0);
      const lastDayLastMonth = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59, 999);
      return d >= firstDayLastMonth && d <= lastDayLastMonth;
    }

    if (period === 'this_quarter') {
      const quarter = Math.floor(now.getMonth() / 3);
      const firstDayQuarter = new Date(now.getFullYear(), quarter * 3, 1, 0, 0, 0, 0);
      const lastDayQuarter = new Date(now.getFullYear(), (quarter + 1) * 3, 0, 23, 59, 59, 999);
      return d >= firstDayQuarter && d <= lastDayQuarter;
    }

    if (period === 'this_year') {
      const firstDayYear = new Date(now.getFullYear(), 0, 1, 0, 0, 0, 0);
      const lastDayYear = new Date(now.getFullYear(), 11, 31, 23, 59, 59, 999);
      return d >= firstDayYear && d <= lastDayYear;
    }

    if (period === 'custom') {
      // Se nenhuma data foi fornecida ainda, não exclui nenhuma proposta
      if (!customStart && !customEnd) return true;

      if (customStart) {
        const start = parseFlexibleDate(customStart);
        if (start && !isNaN(start.getTime())) {
          start.setHours(0, 0, 0, 0);
          if (d < start) return false;
        }
      }
      if (customEnd) {
        const end = parseFlexibleDate(customEnd);
        if (end && !isNaN(end.getTime())) {
          end.setHours(23, 59, 59, 999);
          if (d > end) return false;
        }
      }
      return true;
    }

    return true;
  };

  const getDashboardDateDescription = () => {
    const now = new Date();
    switch (dashboardDateFilter) {
      case 'all': return 'Todo o Período';
      case 'today': return `Hoje (${now.toLocaleDateString('pt-BR')})`;
      case 'this_week': return 'Esta Semana';
      case 'this_month': return `Este Mês (${now.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' })})`;
      case 'last_month': {
        const lm = new Date(now.getFullYear(), now.getMonth() - 1, 1);
        return `Mês Anterior (${lm.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' })})`;
      }
      case 'this_year': return `Ano Vigente (${now.getFullYear()})`;
      case 'custom': {
        if (dashboardStartDate && dashboardEndDate) {
          return `${formatInputDate(dashboardStartDate)} até ${formatInputDate(dashboardEndDate)}`;
        }
        if (dashboardStartDate) {
          return `A partir de ${formatInputDate(dashboardStartDate)}`;
        }
        if (dashboardEndDate) {
          return `Até ${formatInputDate(dashboardEndDate)}`;
        }
        return 'Personalizado';
      }
      default: return 'Todo o Período';
    }
  };

  const dateFilteredSavedExtractions = useMemo(() => {
    if (dashboardDateFilter === 'all') return savedExtractions;
    return savedExtractions.filter(ext => 
      checkDateInPeriod(ext, dashboardDateFilter, dashboardStartDate, dashboardEndDate)
    );
  }, [savedExtractions, dashboardDateFilter, dashboardStartDate, dashboardEndDate]);

  const filteredExtractions = useMemo(() => {
    return dateFilteredSavedExtractions.filter(ext => {
      // 1. Filtrar por status do Dashboard se selecionado
      if (dashboardStatusFilter !== 'todos') {
        const currentStatus = (ext.status || 'na fila').toLowerCase();
        if (dashboardStatusFilter === 'escriturada') {
          const isEscriturada = currentStatus === 'escriturada' || ext.proposta_status === 'ESCRITURADA';
          if (!isEscriturada) return false;
        } else if (dashboardStatusFilter === 'cancelada') {
          const isCancelada = currentStatus === 'cancelada' || ext.proposta_status === 'CANCELADA';
          if (!isCancelada) return false;
        } else if (dashboardStatusFilter === 'aguardando') {
          const propStatus = (ext.proposta_status || 'AGUARDANDO APROVAÇÃO').toUpperCase();
          if (propStatus !== 'AGUARDANDO APROVAÇÃO') return false;
        } else {
          if (currentStatus !== dashboardStatusFilter) return false;
        }
      }

      // 2. Filtrar por termo de busca se preenchido
      if (!searchQuery.trim()) return true;
      const query = searchQuery.toLowerCase();
      const property = ext.property?.empreendimento?.toLowerCase() || '';
      const unit = ext.property?.unidade?.toLowerCase() || '';
      const tower = ext.property?.torre?.toLowerCase() || '';
      const customerNames = (ext.customers || []).map(c => c.nome?.toLowerCase() || '').join(' ');
      const status = ext.status?.toLowerCase() || '';
      const propostaStatus = ext.proposta_status?.toLowerCase() || '';
      const id = ext.id.toLowerCase();
      
      return property.includes(query) || 
             unit.includes(query) || 
             tower.includes(query) || 
             customerNames.includes(query) || 
             status.includes(query) ||
             propostaStatus.includes(query) ||
             id.includes(query);
    });
  }, [dateFilteredSavedExtractions, searchQuery, dashboardStatusFilter]);
  const [showShareModal, setShowShareModal] = useState(false);

  useEffect(() => {
    setDashboardPage(1);
  }, [searchQuery, dashboardStatusFilter, dashboardDateFilter, dashboardStartDate, dashboardEndDate, dashboardPageSize]);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get('mode') === 'readonly') {
      setIsReadOnly(true);
      setView('dashboard');
    }
  }, []);

  const syncUserProfile = async (authenticatedUser: User, customName?: string) => {
    try {
      const userRef = doc(db, 'users', authenticatedUser.uid);
      const userDoc = await getDoc(userRef);
      const isDefaultAdmin = authenticatedUser.email?.toLowerCase() === 'propostasrej@gmail.com';
      if (userDoc.exists()) {
        const role = userDoc.data().role || (isDefaultAdmin ? 'admin' : 'user');
        setUserRole(role);
      } else {
        const initialRole = isDefaultAdmin ? 'admin' : 'user';
        await setDoc(userRef, {
          email: authenticatedUser.email || '',
          displayName: authenticatedUser.displayName || customName || authenticatedUser.email?.split('@')[0] || 'Usuário',
          photoURL: authenticatedUser.photoURL || '',
          role: initialRole,
          created_at: new Date().toISOString()
        });
        setUserRole(initialRole);
      }
    } catch (err: any) {
      if (err.code === 'unavailable' || (err.message && err.message.includes('offline'))) {
        console.warn("Usuário offline, sincronização de perfil adiada.");
      } else {
        console.error("Erro ao sincronizar perfil do usuário:", err);
      }
      if (authenticatedUser.email?.toLowerCase() === 'propostasrej@gmail.com') {
        setUserRole('admin');
      } else {
        setUserRole('user');
      }
    }
  };

