  const handleTestUserWebhook = async () => {
    if (!userWebhookForm.webhookUrl || !userWebhookForm.webhookUrl.startsWith('http')) {
      showToast('Insira uma URL válida iniciando com http:// ou https://', 'error');
      return;
    }
    setIsTestingUserWebhook(true);
    setUserWebhookTestResult(null);
    try {
      const res = await fetch('/api/webhook/test-dispatch', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          url: userWebhookForm.webhookUrl,
          token: userWebhookForm.webhookToken,
          event: userWebhookForm.webhookEvents[0] || 'proposta.recebida',
          userName: selectedUserForWebhook?.displayName || selectedUserForWebhook?.email
        })
      });
      const data = await res.json();
      setUserWebhookTestResult(data);
      if (data.success) {
        showToast(data.message || 'Webhook testado com sucesso!', 'success');
      } else {
        showToast(data.error || 'Falha ao conectar com o Webhook', 'error');
      }
    } catch (err: any) {
      setUserWebhookTestResult({ success: false, error: err.message });
      showToast('Erro ao testar webhook: ' + err.message, 'error');
    } finally {
      setIsTestingUserWebhook(false);
    }
  };

  const handleSaveUserWebhook = async () => {
    if (!selectedUserForWebhook) return;
    setIsSavingUserWebhook(true);
    try {
      const updates = {
        webhookUrl: userWebhookForm.webhookUrl.trim(),
        webhookActive: userWebhookForm.webhookActive,
        webhookToken: userWebhookForm.webhookToken.trim(),
        webhookEvents: userWebhookForm.webhookEvents,
        updated_at: new Date().toISOString()
      };
      await updateDoc(doc(db, 'users', selectedUserForWebhook.id), updates);

      // Update state
      setAllUsers(prev => prev.map(u => u.id === selectedUserForWebhook.id ? { ...u, ...updates } : u));

      // Sincronizar com o backend
      fetch('/api/users/webhooks/sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          users: [{ id: selectedUserForWebhook.id, email: selectedUserForWebhook.email, ...updates }]
        })
      }).catch(() => {});

      showToast('Configuração de Webhook salva com sucesso!', 'success');
      setSelectedUserForWebhook(null);
    } catch (err: any) {
      console.error('Erro ao salvar webhook do usuário:', err);
      showToast('Erro ao salvar no banco: ' + err.message, 'error');
    } finally {
      setIsSavingUserWebhook(false);
    }
  };

