  const handleSyncFromExternalDatabase = async () => {
    if (!user) {
      showToast('Faça login para sincronizar com o banco externo.', 'error');
      return;
    }
    setIsSyncingExternalDb(true);
    try {
      const idToken = await user.getIdToken();
      const res = await fetch('/api/external-app/sync-from-remote', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${idToken}`
        },
        body: JSON.stringify({})
      });
      const data = await res.json();
      if (!res.ok || !data.success) {
        showToast(data.error || 'Falha ao sincronizar com o banco externo.', 'error');
      } else {
        await fetchWebhookProposals();
        await fetchExternalAppStatus();
        showToast(`Sincronização concluída: ${data.importedCount || 0} proposta(s) importada(s).`, 'success');
      }
    } catch (err: any) {
      showToast('Erro de conexão ao sincronizar banco externo: ' + err.message, 'error');
    } finally {
      setIsSyncingExternalDb(false);
    }
  };

