  const handleLoadWebhookProposal = (prop: any, destination: 'extract' | 'rateio' = 'extract') => {
    setResult(prop);
    setIsManualRateio(false);
    setWaterfallResult(null);
    if (prop.manual_waterfall) {
      try {
        const consolidated = obterRateioConsolidado(prop.manual_waterfall);
        const isNfModeProp = isNfRepasseFormaPagamento(prop.forma_pagamento_comissao);
        if (consolidated && (!isNfModeProp || consolidated.detalhesParcelas.length === 1)) {
          setWaterfallResult(consolidated);
          setIsManualRateio(true);
        }
      } catch (e) {
        // fallback
      }
    }
    if (destination === 'extract') {
      setCadastroWindow('proposta');
    }
    setView(destination);
    showToast(`Proposta da Unidade ${prop.property?.unidade || ''} carregada com sucesso!`, 'success');
  };

