  const saveEmpreendimento = async () => {
    if (!user) return;
    if (!empreendimentoForm.nome) {
      setError('O nome do empreendimento é obrigatório.');
      return;
    }

    setIsLoadingEmpreendimentos(true);
    const path = 'empreendimentos';
    try {
      const data = {
        ...empreendimentoForm,
        uid: user.uid,
        updated_at: new Date().toISOString()
      };

      if (editingEmpreendimento) {
        await updateDoc(doc(db, path, editingEmpreendimento.id), data);
      } else {
        await addDoc(collection(db, path), {
          ...data,
          created_at: new Date().toISOString()
        });
      }

      const savedNome = empreendimentoForm.nome.trim();
      const savedLocalizacao = empreendimentoForm.localizacao.trim();
      const savedEndereco = empreendimentoForm.endereco.trim();

      if (view === 'extract' && result) {
        const parts = savedLocalizacao.includes(' - ')
          ? savedLocalizacao.split(' - ')
          : savedLocalizacao.includes('/')
            ? savedLocalizacao.split('/')
            : [savedLocalizacao, ''];
        setResult(prev => prev ? {
          ...prev,
          property: {
            ...prev.property,
            empreendimento: savedNome || prev.property?.empreendimento || '',
            cidade: parts[0]?.trim() || prev.property?.cidade || '',
            estado: parts[1]?.trim() || prev.property?.estado || '',
            endereco: savedEndereco || savedLocalizacao || prev.property?.endereco || ''
          }
        } : null);
      }

      setShowEmpreendimentoModal(false);
      setEditingEmpreendimento(null);
      setEmpreendimentoForm({
        nome: '',
        construtora: '',
        localizacao: '',
        endereco: '',
        tabela_base_id: '',
        status: 'ATIVO',
        regras_comissao: [],
        modelo_rateio: []
      });
      showToast('Empreendimento salvo com sucesso!', 'success');
    } catch (error) {
      handleFirestoreError(error, OperationType.WRITE, path);
    } finally {
      setIsLoadingEmpreendimentos(false);
    }
  };

